def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append((color, cells))

    # Move each rigid object rightward, processing the rightmost objects first.
    components.sort(key=lambda item: max(c for _, c in item[1]), reverse=True)
    occupied = {pos for _, cells in components for pos in cells}

    for _, cells in components:
        while True:
            targets = [(r, c + 1) for r, c in cells]
            if any(c >= w or (r, c) in occupied for r, c in targets):
                break
            occupied.difference_update(cells)
            cells = targets
            occupied.update(cells)

    out = [[0] * w for _ in range(h)]
    for color, cells in components:
        for r, c in cells:
            out[r][c] = color
    return out
